import uuid

from sqlalchemy.exc import IntegrityError
from sqlalchemy.orm import Session

from app.errors import ConflictError, NotFoundError
from app.models import User

# Name generated by the naming convention in models.py.
PHONE_UNIQUE_CONSTRAINT = "uq_users_phone_number"


def get_user(db: Session, user_id: uuid.UUID) -> User:
    user = db.get(User, user_id)
    if user is None:
        raise NotFoundError("User not found")
    return user


def create_user(db: Session, phone_number: str, user_name: str) -> User:
    user = User(phone_number=phone_number, user_name=user_name)
    db.add(user)
    try:
        db.commit()
    except IntegrityError as exc:
        # No "check first, then insert": two requests could both pass the check.
        # The UNIQUE constraint is the source of truth, so insert and handle the clash.
        db.rollback()
        # exc.orig is the psycopg error; its .diag says which constraint was violated.
        diag = getattr(exc.orig, "diag", None)
        if getattr(diag, "constraint_name", None) == PHONE_UNIQUE_CONSTRAINT:
            raise ConflictError("A user with this phone number already exists") from exc
        raise
    db.refresh(user)
    return user
